  await rss.publicarRelatorio({ sendMessage: async (x) => enviados.push(x.embeds[0]) }, itens, { agora: "x" });
  const d = enviados[0].description;
  assert.equal(chamadas, 2, "uma 2ª tentativa só para os que faltaram");
