  ok(busca.rodapeFontes("sem citação", rs, ["q"], { max: 3 }).match(/\]\(</g).length === 2, "  → sem citação: as 2 primeiras");
  ok(busca.rodapeFontes("[1][2][3][4][5]", rs, ["q"], { max: 3 }).match(/\]\(</g).length === 3, "  → com teto, para o rodapé não competir com a resposta");
