  const g = rel.agrupar(ev.filter((e) => e.t >= ate - HORA), { desde: ate - HORA });
  g.persistencia = p;
  const n = rel.montarNumeros({ grupos: g, atividade: new Map(), nomes: new Map(), desde: ate - HORA, ate });
