  class CanalMuitoLento { constructor() { this.id = "C-hora"; this.n = 0; } async sendMessage() { this.n++; throw JSON.stringify({ type: "InSlowmode", retry_after: 3600 }); } }
  sm.instalar(CanalMuitoLento, { duracaoDo: async () => 3600, log: () => {} });
