await m.tocar("CALL_NOVA", "https://www.youtube.com/watch/faixa3");
await m.tocar("CALL_NOVA", "https://www.youtube.com/watch/faixa4");
await espera();
m._trocarDependencias({ conectado: () => false });   // a conexão sumiu por outro caminho
