await voz.sair("CALL_NOVA");
ok(m.fila("CALL_NOVA").atual === null, "★ &sair: a música daquela call acaba junto");
await voz.sair(null);
Module._load = carregar;

console.log(`\nVOZ (volta para a call antiga): ${pass} ok, ${fail} falha(s)`);
