  assert.doesNotMatch(dockerfile, /^FROM node:/m);
  assert.match(dockerfile, /^ARG VULKAN_HEADERS_REF=[0-9a-f]{40}$/m);
  assert.match(dockerfile, /^ARG SD_CPP_REF=[0-9a-f]{40}$/m);
