  rss._interno.parseFeed = async () => { if (++leituras > 1) throw new Error("HTTP 503"); return { titulo: "Notícias", itens: [{ guid: "g1", titulo: "velha 1" }, { guid: "g2", titulo: "velha 2" }] }; };
