for (const f of [DB, DB + "-wal", DB + "-shm", "/tmp/p1-nucleo.json"]) fs.rmSync(f, { force: true });
const U = (n) => `01KNXC${String(n).padStart(20, "0")}`;   // ID com cara de ID do Stoat
const DONO = U(1), OUTRO = U(2), MOD = U(3), ANA = U(4);
